package dns
import("fmt";"net";"sort";"strings")
type SPFRecord struct{Domain string `json:"domain"`;Mechanisms []string `json:"mechanisms,omitempty"`;IP4 []string `json:"ip4,omitempty"`;IP6 []string `json:"ip6,omitempty"`;Include []string `json:"include,omitempty"`;All string `json:"all"`}
func(r SPFRecord)Validate()error{if strings.TrimSpace(r.Domain)==""{return fmt.Errorf("domain is required")};if r.All!=""&&r.All!="pass"&&r.All!="fail"&&r.All!="softfail"&&r.All!="neutral"{return fmt.Errorf("invalid all qualifier")};for _,cidr:=range append(append([]string{},r.IP4...),r.IP6...){if _,_,err:=net.ParseCIDR(strings.TrimSpace(cidr));err!=nil{return fmt.Errorf("invalid network: %s",cidr)}};return nil}
func(r SPFRecord)TXTValue()(string,error){if err:=r.Validate();err!=nil{return "",err};parts:=[]string{"v=spf1"};for _,v:=range r.Mechanisms{if v=strings.TrimSpace(v);v!=""{parts=append(parts,v)}};for _,ip:=range r.IP4{if ip=strings.TrimSpace(ip);ip!=""{parts=append(parts,"ip4:"+ip)}};for _,ip:=range r.IP6{if ip=strings.TrimSpace(ip);ip!=""{parts=append(parts,"ip6:"+ip)}};includes:=append([]string(nil),r.Include...);sort.Strings(includes);for _,inc:=range includes{if inc=strings.TrimSpace(inc);inc!=""{parts=append(parts,"include:"+inc)}};if r.All!=""{parts=append(parts,r.AllQualifier())};return strings.Join(parts," "),nil}
func(r SPFRecord)AllQualifier()string{switch r.All{case "pass":return "+all";case "fail":return "-all";case "softfail":return "~all";case "neutral":return "?all";default:return ""}}
